WITH exploded AS (SELECT id, service, host, log_ts, level, status_code, k, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) e AS k, attr_value) SELECT id, service, host, log_ts, level, k, attr_value, FIRST_VALUE(k) IGNORE NULLS OVER (PARTITION BY k, service ORDER BY log_ts, id, k ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_k, SUM(status_code) OVER (PARTITION BY host ORDER BY status_code, id, k ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_status_code FROM exploded WHERE level = 'DEBUG'
